def clamp_list(xs, lo, hi):
    """Каждый элемент ограничивается отрезком [lo, hi] (lo <= hi)."""
    return [lo if x < lo else hi if x > hi else x for x in xs]

def longest_run(s):
    """Длина самой длинной серии одинаковых подряд идущих символов; для пустой строки 0."""
    if not s:
        return 0
    best = cur = 1
    for prev, ch in zip(s, s[1:]):
        if ch == prev:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    return best

